contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5000, "fee rate too high");

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); if (__ESBMC_reverted()) return;

        bool init = c.initialized(); if (__ESBMC_reverted()) return;
        address baseToken = c.baseToken(); if (__ESBMC_reverted()) return;
        address nft = c.nft(); if (__ESBMC_reverted()) return;
        uint128 virtualBaseTokenReserves = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;
        uint128 virtualNftReserves = c.virtualNftReserves(); if (__ESBMC_reverted()) return;
        uint56 changeFee = c.changeFee(); if (__ESBMC_reverted()) return;
        uint16 feeRate = c.feeRate(); if (__ESBMC_reverted()) return;
        bytes32 merkleRoot = c.merkleRoot(); if (__ESBMC_reverted()) return;
        bool useStolenNftOracle = c.useStolenNftOracle(); if (__ESBMC_reverted()) return;
        bool payRoyalties = c.payRoyalties(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            init &&
            baseToken == _baseToken &&
            nft == _nft &&
            virtualBaseTokenReserves == _virtualBaseTokenReserves &&
            virtualNftReserves == _virtualNftReserves &&
            changeFee == _changeFee &&
            feeRate == _feeRate &&
            merkleRoot == _merkleRoot &&
            useStolenNftOracle == _useStolenNftOracle &&
            payRoyalties == _payRoyalties &&
            reverted
        );
    }
}

